export function FilePreview({
  name = "{{name}}",
  kind = "{{kind}}",
  size = "{{size}}",
  showRemove = {{showRemove}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 280, padding: 10, borderRadius: 10, boxSizing: "border-box", border: "1px solid #24143018", display: "flex", alignItems: "center", gap: 10 }}>
      <div style={{ flex: "none", width: 42, height: 42, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 9, fontWeight: 800, textTransform: "uppercase", color: "#14351f", background: accent }}>{kind}</div>
      <div style={{ flex: "1 1 auto", minWidth: 0 }}>
        <p style={{ margin: 0, fontWeight: 700, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{name}</p>
        <p style={{ margin: "2px 0 0", fontSize: 11, color: "#24143099" }}>{size}</p>
      </div>
      {showRemove && <button type="button" aria-label={`Remove ${name}`} style={{ flex: "none", border: "none", background: "none", cursor: "pointer", color: "#24143099", fontSize: 16, padding: "4px 8px", borderRadius: 6 }}>&times;</button>}
    </div>
  );
}
